/* ── Starstone bonus — +500 per Starstone die in your loadout, applied to every bank.
   triggerCard('starstone', ...) used to silently no-op (starstone is a die,
   not a card — there's no card element to anchor a label to). Now uses
   spawnPop for a visible floating bonus so the player knows it fired. */
if(G.matchDice){
  var _ssCount=G.matchDice.filter(function(m){return m==='starstone';}).length;
  if(_ssCount>0){
    var _ssBonus=_ssCount*500;
    total+=_ssBonus;
    bonusMsg+=' +'+_ssBonus+' ⭐';
    try{spawnPop('+'+_ssBonus+' ⭐ STARSTONE');}catch(e){}
  }
}

