/* WHAT A STARSTONE IS PAID FOR IS BEING KEPT AND SCORED, NOT BEING OWNED.
   Ruling B. Returns the bank bonus owed by ONE committed selection; handleBank
   stamps it onto the kept row and sums the rows at bank time.
   HAND IT THE SCORED HALF OF THE SELECTION, i.e. _splitIcons(sel).rest, never
   the raw selection. selDice still holds the icon-face dice the keep is
   spending, and an icon keep banks zero by design - an icon-face Starstone
   must not pay. .rest is also exactly the set _applyCommitBonuses already
   treats as "the dice that scored" for Vanguard, Hot Hand and the rest, so
   Starstone is now paid on the same participation every other per-commit
   bonus is paid on rather than on a definition invented for it.
   _dieEffect, NOT getDie(d.mat).effect. Routing through _dieEffect is what
   finally puts this trait behind Still Waters: _famHushed is true for a WORKED
   die while confession is live, _dieEffect then returns null, and the die pays
   nothing. Suppression comes for free with the routing - no separate check.
   The old loadout count could never be hushed for the structural reason
   _famHushed's own comment gives for Brass and the shield: it walked
   G.matchDice as bare material ids, with no die object to ask.
   Driven off the MECHANIC rather than the material id, so the one other die
   carrying starstone_bonus - Corvus's Ledger, amount 300 - pays through the
   same path and honours the same gate. */
function _starstonePay(dice){
  var n=0;
  (dice||[]).forEach(function(d){
    var e=_dieEffect(d);
    if(e&&e.mechanic==='starstone_bonus')n+=(e.amount||0);
  });
  return n;
}

/* ss: the Starstone bank bonus this keep earned (ruling B). STAMPED HERE
